<span class="line"><span style="color:#D19A66;">  -H</span><span style="color:#98C379;"> &quot;Authorization: Basic $(</span><span style="color:#56B6C2;">echo</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;admin:Harbor12345&#39; </span><span style="color:#ABB2BF;">|</span><span style="color:#61AFEF;"> base64</span><span style="color:#98C379;">)&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">jq</span><span style="color:#98C379;"> &#39;.metadata&#39;</span></span>
